// Article data for the "Ressources" blog — index page (web/app/ressources/page.tsx)
// and article detail pages (web/app/ressources/[slug]/page.tsx).
//
// Shape ownership:
// - slug, title, categoryBadge, tags, cover, excerpt: owned by the index page (BlogFilterGrid).
// - Detail-page-only fields (e.g. metaDescription, readTime, bodyHtml/sections) may be added
//   by the sibling agent building web/app/ressources/[slug]/page.tsx — keep additions additive,
//   one field per article object, to minimize merge friction.
//
// categoryBadge / tags values match the filter categories used in the .rf-drop[data-dim="cat"]
// dropdown: Stratégie, Site Web, Visibilité, Acquisition, Expérience utilisateur, Publicité, IA, Sécurité.
// data-cats slugs -> label: strategie->Stratégie, site-web->Site Web, visibilite->Visibilité,
// acquisition->Acquisition, experience-utilisateur->Expérience utilisateur, publicite->Publicité,
// ia->IA, securite->Sécurité.

export type ArticleBlock =
  | { type: "lead"; text: string }
  | { type: "h2"; text: string }
  | { type: "h3"; text: string }
  | { type: "p"; text: string }
  | { type: "ul"; items: string[] };

export type Article = {
  slug: string;
  title: string;
  categoryBadge: string;
  tags: string[];
  cover: string;
  excerpt?: string;
  // --- Detail-page fields (web/app/ressources/[slug]/page.tsx) ---
  description: string;
  readTime: string;
  coverAlt: string;
  breadcrumb: string;
  bodyClass: string;
  dataPrefix: string;
  sections: ArticleBlock[];
  calloutTitle: string;
  calloutBody: string;
  // Most articles number their migrated-style data-s attributes as: hero=14, hero
  // container=15, body=16, callout link=17, callout arrow=18, cta band=19 (+bd1/bd2/
  // container/eyebrow/h2/p/btn/arrow/phone = +1..+10 from the cta band number).
  // "ia-web-design" (a4) wraps its <h1> text in an extra data-s span (a4-16), which
  // shifts every subsequent number by +1 (body=17, callout link=18, ..., cta=20).
  // titleDataS is only set for that article; dataOffset captures the shift.
  titleDataS?: string;
  dataOffset?: number;
};

